def transform2(g):
    from collections import Counter
    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    marker=[k for k in c if k!=bg][0]
    out=[]
    for r in g:
        if marker in r:
            last=max(i for i,x in enumerate(r) if x==marker)
            out.append([1 if (i>last and x==bg) else x for i,x in enumerate(r)])
